import gzip, sys
IUPAC={'A':'A','C':'C','G':'G','T':'T','R':'AG','Y':'CT','S':'GC','W':'AT','K':'GT','M':'AC','B':'CGT','D':'AGT','H':'ACT','V':'ACG','N':'ACGT'}
P5='GTGYCAGCMGCCGCGGTAA'
P8='GGACTACNVGGGTWTCTAAT'
PRIMERS=[('F',P5),('R',P8)]

def primer_hit(seq):
    best=None
    for name,p in PRIMERS:
        plen=len(p)
        for off in range(0,6):
            if len(seq) < off+plen: continue
            mm=0
            for a,b in zip(p,seq[off:off+plen]):
                if b not in IUPAC[a]:
                    mm+=1
                    if mm>3: break
            if mm<=3:
                cand=(mm,off,name,plen)
                if best is None or cand<best:
                    best=cand
    return best

def rc(s):
    return s.translate(str.maketrans('ACGTN','TGCAN'))[::-1]

def process(r1_path,r2_path,out1,out2):
    stats={'pairs':0,'skipped':0,'standard':0,'reverse':0,'badroles':0}
    with gzip.open(r1_path,'rt') as f1, gzip.open(r2_path,'rt') as f2, \
         gzip.open(out1,'wt') as o1, gzip.open(out2,'wt') as o2:
        while True:
            h1=f1.readline(); s1=f1.readline(); p1=f1.readline(); q1=f1.readline()
            h2=f2.readline(); s2=f2.readline(); p2=f2.readline(); q2=f2.readline()
            if not h1: break
            stats['pairs']+=1
            s1=s1.strip(); s2=s2.strip()
            h1=primer_hit(s1); h2=primer_hit(s2)
            if h1 is None or h2 is None:
                stats['skipped']+=1; continue
            r1,o1b,n1,l1=h1; r2,o2b,n2,l2=h2
            t1=s1[o1b+l1:]; t2=s2[o2b+l2:]
            if len(t1)<30 or len(t2)<30:
                stats['skipped']+=1; continue
            if n1=='F' and n2=='R':
                f=t1; r=t2; stats['standard']+=1
            elif n1=='R' and n2=='F':
                f=rc(t1); r=rc(t2); stats['reverse']+=1
            else:
                stats['badroles']+=1; continue
            # preserve headers but replace pair suffix to avoid vsearch expecting exact names
            name=h1[1:].split()[0]
            o1.write(f'@{name}1\n{f}\n+\n{"I"*len(f)}\n')
            o2.write(f'@{name}2\n{r}\n+\n{"I"*len(r)}\n')
    print(stats, file=sys.stderr)

if __name__=='__main__':
    process(sys.argv[1],sys.argv[2],sys.argv[3],sys.argv[4])
